mkdir -p /tmp/claude-0/-home-user-engenharia-de-requisitos/dcce4748-9e5c-5235-84e3-4589104d6039/scratchpad && cat > /tmp/claude-0/-home-user-engenharia-de-requisitos/dcce4748-9e5c-5235-84e3-4589104d6039/scratchpad/parse.py <<'EOF'
import sys, html, re
import xml.etree.ElementTree as ET
root = ET.parse(sys.argv[1]).getroot()
cells = {c.get('id'): c for c in root.iter('mxCell')}
kids = {}
for c in cells.values(): kids.setdefault(c.get('parent'), []).append(c)
def txt(v): return re.sub(r'<[^>]+>',' ',html.unescape(v or '')).strip()
for c in cells.values():
    if 'shape=table' in (c.get('style') or ''):
        print('==', txt(c.get('value')), f"[{c.get('id')}]")
        for row in kids.get(c.get('id'), []):
            vals = [txt(x.get('value')) for x in kids.get(row.get('id'), [])]
            print('   ', ' | '.join(v for v in vals if v) or txt(row.get('value')))
print('== EDGES')
for c in cells.values():
    if c.get('edge')=='1':
        print('  ', c.get('source'), '->', c.get('target'), txt(c.get('value')))
print('== OTHER TEXT')
for c in cells.values():
    if c.get('vertex')=='1' and c.get('parent')=='1' and 'shape=table' not in (c.get('style') or '') and c.get('value'):
        print('  ', txt(c.get('value'))[:400])
EOF
